COMMENT ON COLUMN COINS.ID IS 'unique id number identifying coins';
COMMENT ON COLUMN COINS."NAME" IS 'name of coins';
COMMENT ON COLUMN COINS.SLUG IS 'slug names of coins';
COMMENT ON COLUMN COINS.SYMBOL IS 'symbol of names of coins';
COMMENT ON COLUMN COINS."STATUS" IS 'status of coins';
ALTER TABLE COINS MODIFY ("STATUS" ANNOTATIONS (ADD value_description 'commonsense reasoning:• active: this coin is active and available for transactions• untracked: this coin cannot be tracked• inactive: this coin is not available for transactions• extinct: this coin has been disappeared'));
COMMENT ON COLUMN COINS.CATEGORY IS 'category of coins';
ALTER TABLE COINS MODIFY (CATEGORY ANNOTATIONS (ADD value_description 'commonsense reasoning:• token: • coin:'));
COMMENT ON COLUMN COINS.DESCRIPTION IS 'description of coins';
COMMENT ON COLUMN COINS.SUBREDDIT IS 'name of coins on reddit';
COMMENT ON COLUMN COINS.NOTICE IS 'notice if any';
COMMENT ON COLUMN COINS.TAGS IS 'tags of coins';
COMMENT ON COLUMN COINS.TAG_NAMES IS 'tag names of coins';
COMMENT ON COLUMN COINS.WEBSITE IS 'website introduction of coins';
COMMENT ON COLUMN COINS.PLATFORM_ID IS 'id number of the platform';
COMMENT ON COLUMN COINS.DATE_ADDED IS 'the added date';
COMMENT ON COLUMN COINS.DATE_LAUNCHED IS 'lanched date';
COMMENT ON COLUMN HISTORICAL."DATE" IS 'transaction date';
COMMENT ON COLUMN HISTORICAL.COIN_ID IS 'id number referring to coins';
COMMENT ON COLUMN HISTORICAL.CMC_RANK IS 'CMC rank is a metric used by CoinMarketCap to rank the relative popularity of different cryptocurrencies.';
COMMENT ON COLUMN HISTORICAL.MARKET_CAP IS 'Market capitalization refers to how much a coin is worth as determined by the coin market.';
ALTER TABLE HISTORICAL MODIFY (MARKET_CAP ANNOTATIONS (ADD value_description 'dollarsmarket cap (latest trade price x circulating supply).'));
COMMENT ON COLUMN HISTORICAL.PRICE IS 'how much is a coin';
ALTER TABLE HISTORICAL MODIFY (PRICE ANNOTATIONS (ADD value_description 'dollars'));
COMMENT ON COLUMN HISTORICAL."OPEN" IS 'the price at which a cryptocurrency (coin) opens at a time period';
ALTER TABLE HISTORICAL MODIFY ("OPEN" ANNOTATIONS (ADD value_description 'dollarscommonsense reasoning:if null or empty, it means this coins has not opened yet today.'));
COMMENT ON COLUMN HISTORICAL.HIGH IS 'highest price';
ALTER TABLE HISTORICAL MODIFY (HIGH ANNOTATIONS (ADD value_description 'dollars'));
COMMENT ON COLUMN HISTORICAL.LOW IS 'lowest price';
ALTER TABLE HISTORICAL MODIFY (LOW ANNOTATIONS (ADD value_description 'commonsense reasoning:1. It''s the best time to purchase this coin2. users can make the max profit today by computation: high - low'));
COMMENT ON COLUMN HISTORICAL."CLOSE" IS 'the price at which a cryptocurrency (coin) closes at a time period, for example at the end of the day.';
COMMENT ON COLUMN HISTORICAL.TIME_HIGH IS 'the time to achieve highest price';
COMMENT ON COLUMN HISTORICAL.TIME_LOW IS 'the time to achieve lowest price';
COMMENT ON COLUMN HISTORICAL.VOLUME_24H IS 'the total value of cryptocurrency coined traded in the past 24 hours.';
COMMENT ON COLUMN HISTORICAL.PERCENT_CHANGE_1H IS 'price percentage change in the first hour';
ALTER TABLE HISTORICAL MODIFY (PERCENT_CHANGE_1H ANNOTATIONS (ADD value_description 'The change is the difference (in percent) between the price now compared to the price around this time 1 hours ago'));
COMMENT ON COLUMN HISTORICAL.PERCENT_CHANGE_24H IS 'price percentage change in the first 24 hours';
ALTER TABLE HISTORICAL MODIFY (PERCENT_CHANGE_24H ANNOTATIONS (ADD value_description 'The change is the difference (in percent) between the price now compared to the price around this time 24 hours ago'));
COMMENT ON COLUMN HISTORICAL.PERCENT_CHANGE_7D IS 'price percentage change in the first 7 days';
ALTER TABLE HISTORICAL MODIFY (PERCENT_CHANGE_7D ANNOTATIONS (ADD value_description 'The change is the difference (in percent) between the price now compared to the price around this time 7 days ago'));
COMMENT ON COLUMN HISTORICAL.CIRCULATING_SUPPLY IS 'the best approximation of the number of coins that are circulating in the market and in the general public''s hands.';
COMMENT ON COLUMN HISTORICAL.TOTAL_SUPPLY IS 'the total amount of coins in existence right now';
COMMENT ON COLUMN HISTORICAL.MAX_SUPPLY IS 'Max Supply is the best approximation of the maximum amount of coins that will ever exist in the lifetime of the cryptocurrency.';
ALTER TABLE HISTORICAL MODIFY (MAX_SUPPLY ANNOTATIONS (ADD value_description 'commonsense reasoning:the number of coins verifiably burned so far = max_supply - total_supply'));
COMMENT ON COLUMN HISTORICAL.NUM_MARKET_PAIRS IS 'number of market pairs across all exchanges trading each currency.';
ALTER TABLE HISTORICAL MODIFY (NUM_MARKET_PAIRS ANNOTATIONS (ADD value_description 'commonsense reasoning:active coins that have gone inactive can easily be identified as having a num_market_pairs of 0'));